VIEWS.activity = function (v) {
  v.innerHTML = head('سجل الدخول والزيارات', 'كل دخول وكل صفحة يفتحها المستخدمون — آخر 1000 حركة', '', '<button class="btn sec" id="rf">تحديث</button>') + '<div id="al"><div class="loading" style="min-height:30vh"><div class="spin"></div></div></div>';
  var names = { login: 'تسجيل دخول', home: 'الرئيسية', jd: 'وصف وظيفي', kpi: 'مكتبة المؤشرات', emp: 'الموظفون', gov: 'الصلاحيات', eval: 'نموذج التقييم', mine: 'تقييماتي', 'eval-submit': 'إرسال تقييم', 'eval-update': 'تحديث تقييم', inbox: 'صندوق النتائج', users: 'المستخدمون', activity: 'السجل', law: 'الامتثال', settings: 'الإعدادات' };
  var load = function () {
    api('listVisits', { limit: 1000 }).then(function (r) {
      var per = {}; r.visits.forEach(function (x) { var p = per[x[1]] = per[x[1]] || { n: 0, login: 0, name: x[2], last: x[0] }; p.n++; if (x[3] === 'login') p.login++; });
      var st = { q: '' };
      $('#al').innerHTML = '<div class="card" style="margin-bottom:14px"><div class="hd"><h2>عدد الزيارات لكل بريد</h2></div><div class="tw" style="border:0"><table class="t"><thead><tr><th>المستخدم</th><th>مرات الدخول</th><th>كل الحركات</th><th>آخر نشاط</th></tr></thead><tbody>' +
        Object.keys(per).sort(function (a, b) { return per[b].n - per[a].n; }).map(function (k) { var p = per[k]; return '<tr><td><b>' + esc(p.name) + '</b><div class="muted num" style="font-size:12px;text-align:start">' + esc(k) + '</div></td><td class="num">' + p.login + '</td><td class="num">' + p.n + '</td><td class="num">' + esc(p.last) + '</td></tr>'; }).join('') + '</tbody></table></div></div>' +
        '<div class="card" style="margin-bottom:12px"><div class="bd sbox"><label class="f">تصفية حسب البريد أو الاسم<input class="inp" id="aq" type="search"></label></div></div><div class="tw"><table class="t minw"><thead><tr><th>الوقت</th><th>المستخدم</th><th>الحركة</th><th>التفاصيل</th></tr></thead><tbody id="ab"></tbody></table></div>';
      var draw = function () { var q = st.q.toLowerCase(); $('#ab').innerHTML = r.visits.filter(function (x) { return !q || (x[1] + ' ' + x[2]).toLowerCase().indexOf(q) >= 0; }).map(function (x) { return '<tr><td class="num">' + esc(x[0]) + '</td><td>' + esc(x[2]) + '<div class="muted num" style="font-size:11.5px;text-align:start">' + esc(x[1]) + '</div></td><td>' + esc(names[x[3]] || x[3]) + '</td><td class="num">' + esc(x[4]) + '</td></tr>'; }).join('') || '<tr><td colspan="4"><div class="empty">لا توجد حركات</div></td></tr>'; };
      $('#aq').oninput = function () { st.q = this.value; draw(); }; draw();
    }).catch(function (e) { $('#al').innerHTML = '<div class="empty">' + esc(e.message) + '</div>'; });
  };
  $('#rf').onclick = load; load();
};

/* ----- admin: settings */
/* ERP link: export job descriptions + KPIs as one JSON file the L-O ERP imports (format lo-hr.jd-kpi) */
function erpCard() {
  return '<div class="card"><div class="hd"><h2>الربط مع نظام الـ ERP</h2><span class="en">ERP link · Job descriptions &amp; KPIs</span></div><div class="bd stack">' +
    '<div class="muted" style="font-size:12.5px">يصدّر كل الأوصاف الوظيفية ومؤشرات الأداء (' + S.data.jobs.length + ' وصفاً) بملف واحد يُستورد في الـ ERP من صفحة «الأوصاف ومؤشرات الأداء» ← «استيراد ملف الأوصاف». الربط بين النظامين برمز الوظيفة، والملف لا يحتوي بيانات الموظفين.</div>' +
    '<button class="btn pri" id="erpx" style="width:max-content">' + ic('dl') + 'تصدير ملف الأوصاف والمؤشرات للـ ERP</button></div></div>';
}
function exportERP() {
  var pick = function (j) { return { code: j.code, dept: j.dept, en: j.en, ar: j.ar, b: j.b }; };
  var file = { format: 'lo-hr.jd-kpi', version: 1, exportedAt: nowBaghdad(), source: location.href.split('#')[0].replace(/\?.*$/, ''),
    departments: S.data.depts.map(function (d) { return { no: d.no, en: d.en, ar: d.ar }; }), jobs: S.data.jobs.map(pick) };
  saveBlob(new Blob([JSON.stringify(file, null, 1)], { type: 'application/json' }), 'L-O_JD_KPI_for_ERP_' + nowBaghdad().slice(0, 10) + '.json');
  toast('تم تصدير ' + file.jobs.length + ' وصفاً وظيفياً');
}
