/* ---------------------------------------------------------------- editing (admin, or managers given the permission) */
function canEdit(kind, dept) { if (isAdmin()) return true; var p = (S.user && S.user.perms) || {}; return !!p[kind] && (dept == null || myDepts().indexOf(+dept) >= 0); }
function reloadData() { return api('bootstrap').then(function (r) { S.data = r; S.user = r.user; S.evals = r.evals || S.evals; index(); }); }
function profileOf(id) { return (S.data.profiles || {})[id] || {}; }
function orgName(kind, id) { var l = ((S.data.orgs || {})[kind] || []).filter(function (x) { return x.id === id; })[0]; return l ? (l.ar || l.en) : ''; }
function errBox(sel, e) { var m = $(sel); if (m) { m.className = 'msg err'; m.textContent = e.message || e; } }
function twoClick(btn, label, fn) { if (!btn.dataset.ok) { btn.dataset.ok = '1'; var o = btn.innerHTML; btn.textContent = label; setTimeout(function () { if (btn.isConnected && btn.dataset.ok) { delete btn.dataset.ok; btn.innerHTML = o; } }, 4000); return; } fn(); }
function resizeImage(file, max, type, q) {
  return new Promise(function (res, rej) {
    var img = new Image(); img.onerror = function () { rej(new Error('تعذّر قراءة الصورة')); };
    img.onload = function () { var c = document.createElement('canvas'), k = Math.min(1, max / Math.max(img.width, img.height)); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k); var x = c.getContext('2d'); if (type === 'image/jpeg') { x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height); } x.drawImage(img, 0, 0, c.width, c.height); res(c.toDataURL(type, q)); };
    img.src = URL.createObjectURL(file);
  });
}

