/* ----- comprehensive archive: department › employee › evaluations (chronological) */
var AF = { q: '', per: '', type: '', open: {} };
VIEWS.archive = function (v) {
  v.innerHTML = head('الأرشيف الشامل', 'كل التقييمات مرتبة حسب القسم ثم الموظف ثم التاريخ — بترقيم متسلسل', '', '<button class="btn sec" id="arf">تحديث</button><button class="btn sec" id="axl">' + ic('dl') + 'تصدير Excel</button><a class="btn sec" href="#/trash">' + ic('trash') + 'سلة المحذوفات</a>') + '<div id="abx"><div class="loading" style="min-height:30vh"><div class="spin"></div></div></div>';
  var load = function () { return api('listEvals').then(function (r) { S.inbox = r.evals; drawArchive(); }).catch(function (e) { $('#abx').innerHTML = '<div class="empty">' + esc(e.message) + '</div>'; }); };
  $('#arf').onclick = load; $('#axl').onclick = function () { exportCSV(archList()); };
  if (S.inbox) drawArchive(); load();
};
function archList() {
  var q = AF.q.trim().toLowerCase();
  return (S.inbox || []).filter(function (r) { return (!AF.per || r.period === AF.per) && (!AF.type || r.type === AF.type) && (!q || (r.emp.name + ' ' + r.emp.id + ' ' + r.ev.name).toLowerCase().indexOf(q) >= 0); });
}
function drawArchive() {
  var box = $('#abx'); if (!box) return;
  var all = S.inbox || [], list = archList();
  var pers = all.map(function (r) { return r.period; }).filter(function (p, i, a) { return a.indexOf(p) === i; }).sort().reverse();
  var by = {}; list.forEach(function (r) { (by[r.emp.dept] = by[r.emp.dept] || []).push(r); });
  var depts = S.data.depts.map(function (d) { return d.no; }).concat(Object.keys(by).map(Number)).filter(function (n, i, a) { return a.indexOf(n) === i; }).filter(function (n) { return by[n]; });
  box.innerHTML = '<div class="card" style="margin-bottom:12px"><div class="bd sbox"><label class="f">بحث <span class="en">موظف، رقم، مقيّم</span><input class="inp" id="aq" type="search" value="' + esc(AF.q) + '"></label>' +
    '<label class="f">الفترة<select class="inp" id="ap"><option value="">الكل</option>' + pers.map(function (p) { return '<option' + (p === AF.per ? ' selected' : '') + '>' + esc(p) + '</option>'; }).join('') + '</select></label>' +
    '<label class="f">النوع<select class="inp" id="at"><option value="">الكل</option>' + TYPES.map(function (t) { return '<option value="' + t[0] + '"' + (t[0] === AF.type ? ' selected' : '') + '>' + t[1] + '</option>'; }).join('') + '</select></label></div></div>' +
    '<div class="muted" style="font-size:12px;margin-bottom:8px">' + list.length + ' تقييم في ' + depts.length + ' قسم</div>' +
    (depts.length ? depts.map(function (no) {
      var rs = by[no].slice().sort(function (a, b) { return a.emp.name.localeCompare(b.emp.name) || (a.updated < b.updated ? -1 : 1); });
      var emps = {}; rs.forEach(function (r) { (emps[r.emp.id] = emps[r.emp.id] || []).push(r); });
      var seq = 0;
      return '<details class="card arch"' + (AF.open[no] ? ' open' : '') + ' data-no="' + no + '"><summary><span class="num">' + String(no).padStart(2, '0') + '</span> <b>' + esc(deptName(no) || ('قسم ' + no)) + '</b> <span class="muted">— ' + rs.length + ' تقييم · ' + Object.keys(emps).length + ' موظف</span></summary><div class="tw" style="border:0"><table class="t minw"><thead><tr><th>المرجع</th><th>التاريخ</th><th>النوع / الفترة</th><th>المقيِّم</th><th>النهائية</th><th>التقدير</th><th>الحالة</th></tr></thead><tbody>' +
        Object.keys(emps).map(function (eid) { var l = emps[eid], e0 = l[0].emp, j = JOB[e0.code] || {};
          return '<tr class="grp"><td colspan="7"><a href="#/emp/' + encodeURIComponent(eid) + '"><b>' + esc(e0.name) + '</b></a> <span class="num muted">' + esc(eid) + '</span> · ' + esc(j.ar || e0.code) + ' <span class="muted">(' + l.length + ')</span></td></tr>' +
            l.map(function (r) { seq++; return '<tr class="click" data-ev="' + esc(r.id) + '"><td class="num">ARC-' + String(no).padStart(2, '0') + '-' + String(seq).padStart(3, '0') + '</td><td class="num">' + esc(r.updated.slice(0, 10)) + '</td><td>' + TYPE[r.type][1] + ' <span class="num muted">' + esc(r.period) + '</span>' + ppTag(r.pp) + '</td><td>' + esc(r.ev.name) + '</td><td class="num"><b>' + r.F.toFixed(1) + '</b></td><td><span class="pill r' + r.r + '">' + RATES[r.r][0] + '</span></td><td><span class="tag">' + STAT[r.status][1] + '</span>' + (r.archived ? ' <span class="tag">مؤرشف</span>' : '') + '</td></tr>'; }).join('');
        }).join('') + '</tbody></table></div></details>';
    }).join('') : '<div class="empty">لا توجد تقييمات مطابقة</div>');
  $('#aq').oninput = function () { AF.q = this.value; var p = this.selectionStart; drawArchive(); var i = $('#aq'); i.focus(); i.setSelectionRange(p, p); };
  $('#ap').onchange = function () { AF.per = this.value; drawArchive(); };
  $('#at').onchange = function () { AF.type = this.value; drawArchive(); };
  $$('details.arch', box).forEach(function (d) { d.addEventListener('toggle', function () { AF.open[d.dataset.no] = d.open; }); });
  box.onclick = function (e) { var r = e.target.closest('[data-ev]'); if (!r) return; var rec = all.filter(function (x) { return x.id === r.dataset.ev; })[0]; if (rec) openEval(rec, true); };
}
