/* ---------------------------------------------------------------- e-signature + approval workflow */
var SIGROLE = { mgr: 'المقيّم', emp: 'الموظف', head: 'مدير القسم', hr: 'الموارد البشرية', ops: 'مدير العمليات', gm: 'المدير العام', ceo: 'الرئيس التنفيذي' };
